
(()=>{
const qs=(s)=>document.querySelector(s),qsa=(s)=>[...document.querySelectorAll(s)];
const productOrder=['crm','automation','ia','white','systems','sites'];const names={'crm':'CRM & BI','automation':'Integrações e automações','ia':'Agentes de IA','white':'White-label','systems':'Plataformas e sistemas','sites':'Sites premium'};
const tabs=qsa('.showroom-list button[data-scene]'),panels=qsa('.scene-slide');let activeScene=0;function selectScene(index){activeScene=(index+productOrder.length)%productOrder.length;const active=productOrder[activeScene];tabs.forEach(t=>{let yes=t.dataset.scene===active;t.classList.toggle('active',yes);t.setAttribute('aria-selected',String(yes))});panels.forEach(p=>p.classList.toggle('active',p.dataset.panel===active));refreshAtmosphere(active);qs('#stageCount').textContent=String(activeScene+1).padStart(3,'0')+' / 006 · AO VIVO';qs('#briefProduct').value=names[active];}
tabs.forEach((t,i)=>t.addEventListener('click',()=>selectScene(i)));qs('#prevProduct').addEventListener('click',()=>selectScene(activeScene-1));qs('#nextProduct').addEventListener('click',()=>selectScene(activeScene+1));
const nav=qs('#navLinks');qs('#menuToggle').addEventListener('click',e=>{const open=nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.textContent=open?'×':'☰'});qsa('#navLinks a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');qs('#menuToggle').setAttribute('aria-expanded','false');qs('#menuToggle').textContent='☰'}));
const contact=qs('#contactDrawer');function toggleContact(on){contact.classList.toggle('open',on);document.body.classList.toggle('no-scroll',on);if(on)qs('#contactClose').focus()};qsa('.contact-open').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();toggleContact(true)}));qs('#contactClose').addEventListener('click',()=>toggleContact(false));contact.addEventListener('click',e=>{if(e.target===contact)toggleContact(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&contact.classList.contains('open'))toggleContact(false)});
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduced){let tick=0;window.addEventListener('pointermove',e=>{if(window.innerWidth<900)return;if(tick)return;tick=requestAnimationFrame(()=>{const x=(e.clientX/window.innerWidth-.5)*9;const y=(e.clientY/window.innerHeight-.5)*7;qs('#heroScene').style.transform=`rotateY(${-14+x}deg) rotateX(${5-y}deg)`;tick=0})},{passive:true})}
const observer='IntersectionObserver'in window?new IntersectionObserver((entries)=>{entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('visible');observer.unobserve(en.target)}})},{threshold:.04,rootMargin:'0px 0px 90px 0px'}):null;qsa('.reveal').forEach(el=>observer?observer.observe(el):el.classList.add('visible'));
const sectIds=['inicio','experiencias','manifesto','fundador','projetos','contato'];if('IntersectionObserver'in window){const io=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){qsa('.side-index a').forEach((a,i)=>a.classList.toggle('on',sectIds[i]===e.target.id))}})},{rootMargin:'-45% 0px -45% 0px'});sectIds.forEach(id=>{const e=document.getElementById(id);if(e)io.observe(e)})}
// Functional, explicitly simulated agent conversation
qs('#demoChatForm').addEventListener('submit',e=>{e.preventDefault();const inp=qs('#demoChatInput');const txt=inp.value.trim();if(!txt)return;const wrap=qs('#chatBubbles');const user=document.createElement('div');user.className='bubble';user.textContent=txt;wrap.appendChild(user);const reply=document.createElement('div');reply.className='bubble ai';reply.textContent=/preço|valor|quanto/i.test(txt)?'O valor depende do serviço. Posso entender melhor o que você procura e encaminhar uma estimativa?':/horário|agenda|agendar|dia/i.test(txt)?'Claro! Posso verificar a disponibilidade e encaminhar suas preferências para a equipe. Você prefere manhã ou tarde?':'Entendi! Posso te ajudar com as informações e encaminhar sua solicitação para o atendimento. O que você gostaria de saber primeiro?';wrap.appendChild(reply);inp.value='';wrap.scrollTop=wrap.scrollHeight});
// Interactive automation simulation (no backend)
let flowTimers=[];qs('#runFlow').addEventListener('click',()=>{flowTimers.forEach(clearTimeout);flowTimers=[];const nodes=qsa('#flowChain .flow-node');nodes.forEach(n=>n.classList.remove('done'));qs('#flowStatus').textContent='Processando...';nodes.forEach((n,i)=>flowTimers.push(setTimeout(()=>{n.classList.add('done');qs('#flowStatus').textContent=i===nodes.length-1?'Simulação concluída · 4/4 etapas':`Executando etapa ${i+1} / 4`},(i+1)*470)))});
qsa('[data-brand]').forEach(b=>b.addEventListener('click',()=>{qs('#whiteDemo').style.setProperty('--brand-color',b.dataset.brand);qsa('[data-brand]').forEach(x=>x.classList.toggle('selected',x===b))}));
// Form submit handled by V25 Netlify/fallback module below.

const sceneCodes={crm:'01 / COMMERCIAL INTELLIGENCE',automation:'02 / ORCHESTRATION ENGINE',ia:'03 / CONVERSATIONAL INTELLIGENCE',white:'04 / BRAND-OWNED PLATFORMS',systems:'05 / CUSTOM OPERATIONS',sites:'06 / DIGITAL EXPERIENCES'};
const showroom=qs('#showroom'),studioEditorial=qs('#sceneEditorial'),progress=[...document.querySelectorAll('#labProgress span')];
function refreshAtmosphere(scene){
 showroom.dataset.environment=scene;
 studioEditorial.textContent=sceneCodes[scene]||scene.toUpperCase();
 progress.forEach((node,i)=>node.classList.toggle('on',i===productOrder.indexOf(scene)));
}
// Elegant localised light response, no background-wide cursor trails.
if(!reduced){const museumStage=qs('.showroom-stage');let last=0;museumStage?.addEventListener('pointermove',event=>{if(window.innerWidth<901)return;if(last)cancelAnimationFrame(last);last=requestAnimationFrame(()=>{const r=museumStage.getBoundingClientRect();museumStage.style.setProperty('--mx',`${((event.clientX-r.left)/r.width)*100}%`);museumStage.style.setProperty('--my',`${((event.clientY-r.top)/r.height)*100}%`);last=0})},{passive:true})}

qsa('[data-product-link]').forEach(a=>a.addEventListener('click',()=>selectScene(productOrder.indexOf(a.dataset.productLink))));
selectScene(0);
})();



(()=>{
 const hero=document.querySelector('.kin-hero');if(!hero)return;
 const buttons=[...hero.querySelectorAll('[data-kin-switch]')];
 const copies=[...hero.querySelectorAll('[data-kin-copy]')];
 const scenes=[...hero.querySelectorAll('[data-kin-scene]')];
 const pause=hero.querySelector('#kinPause');
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const total=4; const categories=['CRM · BI','AGENTES IA','INTEGRAÇÕES','SITES PREMIUM']; const category=hero.querySelector('#kinCategory');let current=0;let playing=!reduced;let timer=null;
 const duration=6700;
 function schedule(){clearTimeout(timer);if(playing && !document.hidden){timer=setTimeout(()=>show((current+1)%total),duration)}}
 function show(index){current=(index+total)%total;copies.forEach((el,i)=>el.classList.toggle('is-current',i===current));scenes.forEach((el,i)=>el.classList.toggle('is-current',i===current));buttons.forEach((el,i)=>{el.classList.toggle('is-active',i===current);el.classList.toggle('is-playing',i===current&&playing);el.setAttribute('aria-pressed',String(i===current));if(i===current){const t=el.querySelector('.kin-timeline');t.style.animation='none';void t.offsetWidth;t.style.animation='';}});hero.querySelector('#kinCounter').textContent=`0${current+1} / 04`;if(category)category.textContent=categories[current];schedule()}
 buttons.forEach((b,i)=>b.addEventListener('click',()=>show(i)));
 pause.addEventListener('click',()=>{playing=!playing;pause.textContent=playing?'Ⅱ':'▶';pause.setAttribute('aria-label',playing?'Pausar animação':'Retomar animação');pause.setAttribute('aria-pressed',String(!playing));show(current)});
 document.addEventListener('visibilitychange',()=>schedule());
 hero.querySelector('#kinExplore')?.addEventListener('click',()=>{playing=false;show(current)});
 show(0);
})();

(()=>{
'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const form=$('#briefForm'),result=$('#briefResult');if(!form||!result)return;
const submitBtn=form.querySelector('button[type="submit"]')||form.querySelector('button');
const makeMessage=fd=>`Olá! Vim pelo site AIBeck e gostaria de solicitar um diagnóstico.\n\nNome: ${fd.get('nome')}\nEmpresa: ${fd.get('empresa')}\nContato: ${fd.get('contato')}\nSolução: ${fd.get('produto')}\nMomento: ${fd.get('momento')}\nDesafio: ${fd.get('desafio')||'A definir'}`;
const showFallback=(message,heading)=>{
result.replaceChildren();const p=document.createElement('p');p.textContent=heading;result.append(p);
const copy=document.createElement('button');copy.type='button';copy.textContent='Copiar briefing';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(message);copy.textContent='Copiado ✓'}catch{const ta=document.createElement('textarea');ta.value=message;document.body.append(ta);ta.select();document.execCommand('copy');ta.remove();copy.textContent='Copiado ✓'}});
const insta=document.createElement('a');insta.href='https://www.instagram.com/ai.beck_/';insta.target='_blank';insta.rel='noopener noreferrer';insta.textContent='Conversar pelo Instagram ↗';insta.className='v25-instagram-link';result.append(copy,insta)};
form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const fd=new FormData(form),msg=makeMessage(fd);const isLocal=location.protocol==='file:'||['localhost','127.0.0.1'].includes(location.hostname);
if(isLocal){showFallback(msg,'Prévia local: seus dados não foram enviados. Copie o briefing e entre em contato para solicitar o diagnóstico.');return;}
submitBtn.disabled=true;submitBtn.textContent='Enviando solicitação...';try{const response=await fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(fd).toString()});if(!response.ok)throw new Error('Falha na solicitação');result.textContent='Solicitação recebida pelo formulário. Obrigado! Nossa equipe poderá entrar em contato pelos dados informados.';window.aiTrack?.('lead_success',{product:String(fd.get('produto')||'')});form.reset()}catch(e){showFallback(msg,'Não foi possível confirmar o recebimento automático neste domínio. Copie o briefing e fale com a AIBeck pelo Instagram.')}finally{submitBtn.disabled=false;submitBtn.textContent='Solicitar diagnóstico ↗'}});
$$('.v25-contact-trigger').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();const product=b.dataset.product||'CRM & BI';const sel=$('#briefProduct');if(sel&&[...sel.options].some(o=>o.textContent===product))sel.value=product;const c=$('#contactDrawer');c?.classList.add('open');document.body.classList.add('no-scroll');$('#contactClose')?.focus()}));
})();

