function afBlueprintGenerate(){
 const key=document.getElementById('af-diag-segment').value;
 const pain=document.getElementById('af-diag-pain').value;
 const stack=document.getElementById('af-diag-stack').value;
 const priority=document.getElementById('af-diag-priority').value;
 const t=afTemplates[key],recs=afDiagRecommendations[pain],size=S.deals.length,qualified=S.contacts.filter(c=>c.score).length;
 afBlueprintText=`DIAGNÓSTICO PRELIMINAR AIBECK\nSegmento: ${t.label}\nDesafio: ${afDiagLabels[pain]}\nFerramentas: ${stack}\nPrioridade: ${priority}\n\nARQUITETURA RECOMENDADA\n${recs.map((r,i)=>`${i+1}. ${r}`).join('\n')}\n\nETAPAS SUGERIDAS\n1. Diagnóstico e desenho do processo atual.\n2. Configuração de dados, canais e responsáveis.\n3. Testes, treinamento e acompanhamento de ativação.\n\nExperiência demonstrativa: ${size} negócios e ${qualified} contatos qualificados (dados simulados).\n\nPlano inicial sujeito a validação técnica, privacidade, direitos de plataforma e proposta comercial.`;
 const result=document.getElementById('af-diagnostic-result');
 result.innerHTML=`<div class="af-result-top"><span class="af-kicker">AIBECK / SEU BLUEPRINT</span><span class="af-pill">GERADO AGORA · PRELIMINAR</span></div><div class="af-result-intro"><span>${esc(t.label.toUpperCase())} / ARQUITETURA</span><h3>Uma operação desenhada para o seu cenário.</h3><p><b>Desafio:</b> ${esc(afDiagLabels[pain])}<br><b>Prioridade:</b> ${esc(priority)}</p></div><div class="af-recommendations">${recs.map((r,i)=>`<div><small>0${i+1}</small><strong>${esc(r)}</strong></div>`).join('')}</div><div class="af-implementation"><span>TRILHA DE IMPLEMENTAÇÃO</span><p>Diagnóstico e desenho → Configuração e integrações → Testes, treinamento e ativação assistida.</p></div><p class="af-legal-note">Plano indicativo — não é orçamento, contrato, previsão de resultados ou solução já implantada.</p><div class="af-result-actions"><button class="af-primary" type="button" id="af-convert">Quero esse projeto na minha empresa ↗</button><button type="button" class="af-quiet" id="af-copy">Copiar diagnóstico</button></div>`;
}
