(()=>{
 const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches||false;
 const mobile=window.matchMedia?.('(max-width: 700px)').matches||false;
 const fps=mobile?13:22, step=1000/fps;
 const pick=(a,i)=>a[(i+a.length)%a.length];
 const canvases=document.querySelectorAll('canvas[data-ab-fx]');
 const instances=[];
 canvases.forEach(canvas=>{
  const parent=canvas.parentElement, ctx=canvas.getContext('2d',{alpha:true});if(!ctx)return;
  let w=1,h=1,visible=true,raf=0,last=0,tx=.5,ty=.5;
  const points=Array.from({length:85},(_,i)=>({x:((i*73.73)%100)/100,y:((i*37.17)%100)/100,r:0.4+(i*13%9)/10,z:.3+(i*17%19)/19}));
  function resize(){const r=canvas.getBoundingClientRect();w=Math.max(1,Math.round(r.width));h=Math.max(1,Math.round(r.height));const dpr=Math.min(window.devicePixelRatio||1,1.35);canvas.width=Math.max(1,Math.round(w*dpr));canvas.height=Math.max(1,Math.round(h*dpr));ctx.setTransform(dpr,0,0,dpr,0,0);paint(performance.now())}
  function paint(now){const time=now*.00015;ctx.clearRect(0,0,w,h);
    if(canvas.dataset.abFx==='galaxy'){
      const halo=ctx.createRadialGradient(w*.69,h*.42,0,w*.69,h*.42,Math.max(w,h)*.55);
      halo.addColorStop(0,'rgba(35,142,235,.12)');halo.addColorStop(.55,'rgba(40,120,255,.035)');halo.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=halo;ctx.fillRect(0,0,w,h);
      for(const p of points){const drift=reduced?0:time*p.z;const x=(p.x*w+drift*17)%(w+30)-15;const y=(p.y*h+Math.sin(drift+p.x*18)*8+h)%h;const dx=x-tx*w,dy=y-ty*h;const dist=Math.hypot(dx,dy);const f=Math.max(0,1-dist/155);const px=x+(dx/Math.max(dist,1))*f*12,py=y+(dy/Math.max(dist,1))*f*12;
        const twinkle=.45+.45*Math.sin(reduced?1:time*8+p.x*93);ctx.fillStyle=`rgba(146,223,255,${(.15+p.z*.30)*twinkle})`;ctx.beginPath();ctx.arc(px,py,p.r,0,Math.PI*2);ctx.fill();
        if(p.z>.9){ctx.strokeStyle=`rgba(126,221,255,${.13*twinkle})`;ctx.beginPath();ctx.moveTo(px-6,py);ctx.lineTo(px+6,py);ctx.moveTo(px,py-6);ctx.lineTo(px,py+6);ctx.stroke()}
      }
    }else{
      const chars=' =+xX0S8#@'; const cw=mobile?15:18,ch=mobile?18:22;
      const cols=Math.ceil(w/cw),rows=Math.ceil(h/ch);
      const palette=['#3269e6','#5c9bfd','#a1e5ff','#e8faff'];ctx.font=`${mobile?11:13}px ui-monospace,Menlo,Consolas,monospace`;ctx.textAlign='center';ctx.textBaseline='middle';
      for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
        const x=c*cw+cw/2,y=r*ch+ch/2;const nx=x/w,ny=y/h;
        const wave=.54+Math.sin(nx*4.5+(reduced?0:time*.55))*.08+Math.cos(nx*8)*.022;
        const ridge=Math.max(0,1-Math.abs(ny-wave)*3.4);const horizon=Math.max(0,ny*.56+ridge*.64);
        const noise=(Math.sin(c*81.9+r*46.1)*43758.5453)%1;
        const level=Math.min(1,Math.max(0,horizon+.14*Math.sin(nx*4+(reduced?0:time*.34))));
        const ci=Math.floor(Math.max(0,Math.min(3,level*3.3)));const shade=Math.max(0,Math.min(chars.length-1,Math.floor(level*(chars.length-1)+noise*.8)));
        const alpha=(.09+ridge*.40)*(0.6+.4*Math.abs(noise));if(alpha<.11||ny<.26&&ridge<.22)continue;
        ctx.globalAlpha=alpha;ctx.fillStyle=palette[ci];ctx.fillText(pick(chars,shade),x,y)
      }
      ctx.globalAlpha=1;
    }
  }
  function animate(now){raf=0;if(document.hidden||!visible)return;if(now-last>=step){paint(now);last=now}if(!reduced)raf=requestAnimationFrame(animate)}
  function wake(){if(!raf&&!reduced&&!document.hidden&&visible)raf=requestAnimationFrame(animate)}
  const observer=new IntersectionObserver(es=>{visible=es.some(x=>x.isIntersecting);if(visible){paint(performance.now());wake()}else if(raf){cancelAnimationFrame(raf);raf=0}});observer.observe(canvas);
  const ro=new ResizeObserver(resize);ro.observe(canvas);
  function pointer(e){const rect=parent.getBoundingClientRect();tx=(e.clientX-rect.left)/Math.max(rect.width,1);ty=(e.clientY-rect.top)/Math.max(rect.height,1)}
  parent.addEventListener('pointermove',pointer,{passive:true});resize();wake();instances.push({wake});
 });
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)instances.forEach(x=>x.wake())});
})();
